# Function to calculate the number of divisors of x^2
def tau_x_squared(x):
    if x == 1:
        return 1
    n = x
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1

    tau = 1
    for p, e in factors.items():
        # If x = p1^e1 * p2^e2 * ...
        # then x^2 = p1^(2*e1) * p2^(2*e2) * ...
        # The number of divisors tau(x^2) is (2*e1 + 1) * (2*e2 + 1) * ...
        tau *= (2 * e + 1)
    return tau

