def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x_squared(x):
    if x == 1:
        return 1
    factors_x = prime_factorization(x)
    tau = 1
    for prime, exponent in factors_x.items():
        # For x^2, the exponent is 2*exponent
        tau *= (2 * exponent + 1)
    return tau

MAX_X = 1717
